function dedupeRoster(items){const seen=new Set(),out=[];for(const x of items){const k=[x.date,x.shift,idKey(x.server),x.source].join('|');if(seen.has(k))continue;seen.add(k);out.push(x)}return out}

function reportName(r){return normName(r?.employee||r?.employeeDisplayName||r?.name||r?.personName)}
function reportPosition(r){return txt(r?.position||r?.role||r?.employeeSheetRow?.role||r?.employeeSheetRow?.position)}
function batchTeamMembers(batch){const team=Array.isArray(batch?.team)?batch.team:Object.values(batch?.team&&typeof batch.team==='object'?batch.team:{});return team.filter(Boolean).map(member=>{const name=normName(typeof member==='string'?member:(member?.name||member?.employee||member?.server));const role=txt(typeof member==='object'?(member?.position||member?.role):'');return {name,role}}).filter(x=>x.name)}
