function reportHours(r){return num(r.totalHoursWork??r.totalHours??r.hoursWorked??r.hours?.totalHours??(num(r.totalMinutesWork)/60))}
function shiftBucket(r){const s=txt(r.shift).toUpperCase();if(s==='AM'||s.includes('10:45 - 14:00'))return 'AM';if(s==='PM'||s.includes('14:00 - 16:00'))return 'PM';return 'ALL'}
function reportSales(r){return num(r.grandTotal)}
