function reportPayout(r){return num(r.totalPaidOut??r.grandTotalAfterAdjustment??r.finalPaidOut)}
function reportBusser(r){return num(r.busserTipOut??r.busserTotal??num(r.busserTipOutAM)+num(r.busserTipOutPM))}
function reportBarOut(r){return num(r.barTipOut??r.totalBarTipOut??num(r.barTipOutAM)+num(r.barTipOut24)+num(r.barTipOutPM))}
