 if(a.incomplete.length)pdfText(d,id?`${a.incomplete.length} server belum ikut ranking karena datanya belum lengkap.`:`${a.incomplete.length} server(s) are not ranked because their data are incomplete.`,520,565,242,7.6,[120,92,28],'bold');
