 if(rot)pdfText(d,id?`${rot.name} berada di bawah standar tetapi kesempatan mejanya rendah. Cek section/skip/rotasi sebelum coaching.`:`${rot.name} is below standard but table opportunity is low. Check section/skips/rotation before coaching.`,412,555,350,7.2,[120,92,28],'bold');
 pdfText(d,L.incomplete,30,585,730,7.2,[107,124,139],'bold');
