function pdfMenu(){$('modalTitle').textContent='3-Page PDF • Page 1 Executive Summary';$('modalBody').innerHTML=`<div class="grid2"><button class="btn primary" id="pdfEN" style="padding:32px;font-size:20px">English • 3 Pages</button><button class="btn gold" id="pdfID" style="padding:32px;font-size:20px">Bahasa Indonesia • 3 Halaman</button></div><div class="recommend" style="margin-top:14px"><b>What is inside:</b> Page 1 is a plain-language Executive Summary built from all rankings. Page 2 shows every server's rank across all 15 aspects. Page 3 combines All Summary, each server's strongest positions, coaching reasons, rotation context, and manager actions.</div>`;$('modal').classList.remove('hidden');$('pdfEN').onclick=()=>pdfReport('EN');$('pdfID').onclick=()=>pdfReport('ID')}
async function ownerLogin(){const u=$('user').value.trim(),p=$('pass').value;if(!u||!p)return $('loginMsg').textContent='Enter owner username and password.';const btn=$('loginBtn');try{btn.disabled=true;$('loginMsg').textContent='Signing in…';await signInWithEmailAndPassword(auth,emailFor(u),p)}catch(e){console.error('Owner login:',e);$('loginMsg').textContent='Login failed: '+(e.code||e.message||'unknown error')}finally{btn.disabled=false}}
$('loginBtn').onclick=ownerLogin;
$('pass').addEventListener('keydown',e=>{if(e.key==='Enter')ownerLogin()});
onAuthStateChanged(auth,async user=>{if(!user){profile=null;$('loginView').classList.remove('hidden');$('app').classList.add('hidden');return}try{$('loginMsg').textContent='Verifying Owner account…';const s=await getDoc(doc(db,'users',user.uid));const p=s.exists()?s.data():null;if(!p||p.active===false||p.role!=='owner'){await signOut(auth);$('loginMsg').textContent='Owner account required.';return}profile=p;$('ownerName').textContent=p.displayName||p.username||'OWNER';$('loginMsg').textContent='';$('loginView').classList.add('hidden');$('app').classList.remove('hidden');setMode('daily');if(timer)clearInterval(timer);timer=setInterval(refreshBoard,30000)}catch(e){console.error('Owner verification:',e);try{await signOut(auth)}catch(_){}$('loginView').classList.remove('hidden');$('app').classList.add('hidden');$('loginMsg').textContent='Owner verification failed: '+(e.code||e.message||'unknown error')}});
$('logoutBtn').onclick=()=>signOut(auth);$('refreshBtn').onclick=()=>{state.from=$('from').value;state.to=$('to').value;state.shift=$('shift').value;subscribeTips();refreshBoard()};$('aliasBtn').onclick=identityModal;$('pdfBtn').onclick=pdfMenu;$('modalClose').onclick=()=>$('modal').classList.add('hidden');$('modal').addEventListener('click',e=>{if(e.target===$('modal'))$('modal').classList.add('hidden')});
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>setMode(b.dataset.mode));document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('on',x===b));renderContent()});$('shift').onchange=()=>{state.shift=$('shift').value};
let deferredInstallPrompt=null;const installButtons=[$('installBtn'),$('loginInstallBtn')].filter(Boolean);function refreshInstallButtons(){installButtons.forEach(b=>b.classList.toggle('hidden',!deferredInstallPrompt))}window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;refreshInstallButtons()});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;refreshInstallButtons()});installButtons.forEach(b=>b.onclick=async()=>{if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();try{await deferredInstallPrompt.userChoice}catch(e){}deferredInstallPrompt=null;refreshInstallButtons()});
$('resetCacheBtn')?.addEventListener('click',async()=>{try{if('serviceWorker'in navigator){const regs=await navigator.serviceWorker.getRegistrations();await Promise.all(regs.map(r=>r.unregister()))}if('caches'in window){const keys=await caches.keys();await Promise.all(keys.filter(k=>k.startsWith('fz-server-intelligence')).map(k=>caches.delete(k)))}$('loginMsg').textContent='App cache cleared. Reloading…';setTimeout(()=>location.reload(true),350)}catch(e){$('loginMsg').textContent='Cache reset failed: '+(e.message||e)}});
